// Fallback illustration for a service without a usable photo, chosen by its code or name.
// The SVGs are generated by scripts/assets/generate-service-illustrations.mjs.

const RULES: ReadonlyArray<readonly [string, RegExp]> = [
  ['catering', /cater|comida|alimento|meal/],
  ['baggage', /baggage|equipaje|maleta|luggage/],
  ['cargo', /cargo|carga|descarga|uld|paleta|pallet/],
  ['cleaning', /clean|limpi|aseo|cabin/],
  ['fuel', /fuel|combustib|abastec|jet\s?a/],
  ['pmr', /pmr|prm|wheelchair|silla|movilidad|asistencia especial/],
  ['power', /gpu|power|energ|generad/],
  ['aircon', /\bac\b|-ac\b|air\s?cond|aire acond|pca/],
  ['stairs', /stair|escaler/],
  ['towing', /tow|remolq|push\s?back|tractor/],
  ['marshalling', /parking|marshal|señal|parque/],
  ['boarding', /board|embarq|pasarela|bridge|pasajer/],
];

export function serviceIllustrationKind(service: { code?: string | null; name?: string | null } | null | undefined): string {
  const text = `${service?.code ?? ''} ${service?.name ?? ''}`.toLocaleLowerCase('es');
  return RULES.find(([, pattern]) => pattern.test(text))?.[0] ?? 'aircraft';
}

export function serviceImageFallback(service: { code?: string | null; name?: string | null } | null | undefined): string {
  return `/assets/services/illustrations/${serviceIllustrationKind(service)}.svg`;
}
